#nullable enable // autogenerated

using MVZ2.GameContent.Buffs;
using MVZ2.GameContent.Buffs.Projectiles;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Contraptions
{
    public class PrismPylonProjectileModePurple : PrismPylonProjectileMode
    {
        public override NamespaceID GetModeBuffID()
        {
            return VanillaBuffID.Projectile.prismPylonProjectilePurple;
        }
        public override Vector3 GetHSV(Entity entity, Entity oldProjectile)
        {
            return new Vector3(315, 0, 0);
        }
        public override Color GetLightColor(Entity entity, Entity oldProjectile)
        {
            return new Color(1, 0, 0.75f, 1);
        }
        public override void ApplyToBuff(Entity entity, Entity oldProjectile, Buff buff)
        {
            base.ApplyToBuff(entity, oldProjectile, buff);
            HomingProjectileBuff.SetSpeed(buff, Mathf.Max(10, oldProjectile.Velocity.magnitude));
        }
    }
}
